await page.goto('/login');

const info = await page.evaluate(() => {
  const z = (el) => {
    let n = el;
    while (n && n !== document.documentElement) {
      const v = getComputedStyle(n).zIndex;
      if (v !== 'auto') return parseInt(v, 10);
      n = n.parentElement;
    }
    return 0;
  };
  const find = (re) =>
    [...document.querySelectorAll('*')].filter((e) => {
      const s = (e.className && e.className.toString ? e.className.toString() : '') + ' ' + (e.id || '') + ' ' + (e.getAttribute('data-testid') || '');
      return re.test(s);
    });
  const backdrop = find(/backdrop/i)[0];
  const bar = find(/landing[-_ ]?bar|landingbar|topbar|top-bar|statusbar/i)[0];
  return {
    backdropZ: backdrop ? z(backdrop) : null,
    barZ: bar ? z(bar) : null,
  };
});

// Both layers must stay above the base page content (z-index 0), not drop below it.
expect(info.backdropZ).not.toBeNull();
expect(info.barZ).not.toBeNull();
expect(info.backdropZ > 0).toBe(true);
expect(info.barZ > 0).toBe(true);
